control-state.command:
read_setting() {
  s=$(settings get "$@" 2>/dev/null) || return
  case "$s" in ''|*[!0-9]*) ;; *) printf '%s' "$s";; esac
}
read_display_brightness() {
  # Modern SystemUI uses BrightnessInfo for the default display, not the legacy integer.
  d=$(dumpsys -t 2 display 2>/dev/null | awk -F= '
    /^[[:space:]]*Display Power Controller:[[:space:]]*$/ { id = "" }
    /^[[:space:]]*mDisplayId=/ { id = $2 == "0" }
    id && /^[[:space:]]*mCachedBrightnessInfo\.brightness=/ { level = $2 }
    id && /^[[:space:]]*mCachedBrightnessInfo\.brightnessMin=/ { low = $2 }
    id && /^[[:space:]]*mCachedBrightnessInfo\.brightnessMax=/ { high = $2 }
    function unit(v) { return v ~ /^[0-9]*\.?[0-9]+([eE][+-]?[0-9]+)?$/ && v + 0 >= 0 && v + 0 <= 1 }
    END { if (unit(level) && unit(low) && unit(high) && low + 0 < high + 0) print level "," low "," high }
  ')
  if [ -n "$d" ]; then printf '%s' "$d"; return; fi
  # Android 11 SystemUI reads the float setting with PowerManager's configured range.
  # Newer devices may still have a stale copy of this setting after an OS upgrade.
  [ "$(getprop ro.build.version.sdk 2>/dev/null)" = 30 ] || return
  level=$(settings get --user current system screen_brightness_float 2>/dev/null) || return
  case "$level" in ''|*[!0-9.eE+-]*) return;; esac
  range=$(dumpsys -t 2 power 2>/dev/null | awk -F= '
    /^[[:space:]]*mScreenBrightnessSettingMinimumFloat=/ { low = $2 }
    /^[[:space:]]*mScreenBrightnessSettingMaximumFloat=/ { high = $2 }
    END { if (low != "" && high != "") print low "," high }
  ')
  if [ -n "$range" ]; then printf '%s,%s' "$level" "$range"; fi
}
w=$(cmd wifi status 2>/dev/null) || w=
ws=$(printf '%s\n' "$w" | awk 'tolower($0) ~ /^[[:space:]]*wi-?fi is (enabled|disabled|enabling|disabling|unknown)[[:space:]]*$/ { print tolower($3); exit }')
# Some cmd wifi versions report transitions as disabled. Check the actual service state.
if [ "$ws" = disabled ] || [ -z "$ws" ]; then
  wd=$(dumpsys -t 2 wifi 2>/dev/null | awk 'tolower($0) ~ /^[[:space:]]*wi-?fi is (enabled|disabled|enabling|disabling|unknown)[[:space:]]*$/ { print tolower($3); exit }')
  ws=${wd:-$ws}
fi
case "$ws" in
  enabled)
    wifi=1
    wc=$(printf '%s\n' "$w" | awk 'tolower($0) ~ /^[[:space:]]*wi-?fi is connected( to |[[:space:]]*$)/ { print 1; exit } tolower($0) ~ /^[[:space:]]*wi-?fi is (not connected|disconnected)[[:space:]]*$/ { print 0; exit }');;
  disabled) wifi=0; wc=0;;
  *) wifi=; wc=;;
esac
bt=$(dumpsys -t 2 bluetooth_manager 2>/dev/null | awk 'tolower($1) == "state:" { print toupper($2); exit }')
case "$bt" in
  ON|STATE_ON|12) bt=1;;
  OFF|STATE_OFF|10|BLE_ON|STATE_BLE_ON|15) bt=0;;
  '') bt=$(read_setting global bluetooth_on); case "$bt" in 0|1) ;; *) bt=;; esac;;
  *) bt=;;
esac
v=$(cmd media_session volume --stream 3 --get 2>/dev/null) || v=
volume=$(printf '%s\n' "$v" | sed -nE 's/^[[:space:]]*(\[[Vv]\][[:space:]]+)?volume is ([0-9]+) in range \[([0-9]+)\.\.([0-9]+)\][[:space:]]*$/\2,\3,\4/p' | head -n 1)
printf 'wifi=%s\nwifi_connected=%s\nbluetooth=%s\nairplane=%s\nbrightness=%s\ndisplay_brightness=%s\nauto_brightness=%s\nvolume=%s\n' "$wifi" "$wc" "$bt" "$(read_setting global airplane_mode_on)" "$(read_setting --user current system screen_brightness)" "$(read_display_brightness)" "$(read_setting --user current system screen_brightness_mode)" "$volume"
